#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "lang.h"
#include "util.h"

char *build_lang_regex(const size_t *chosen, size_t chosen_len) {
    strbuf_t sb;
    size_t i, j;
    int first = 1;

    sb_init(&sb);
    sb_append(&sb, "\\.(");
    for (i = 0; i < chosen_len; i++) {
        const lang_spec_t *l = &langs[chosen[i]];
        for (j = 0; j < LANG_MAX_EXTS && l->exts[j] != NULL; j++) {
            if (!first) {
                sb_append(&sb, "|");
            }
            sb_append(&sb, l->exts[j]);
            first = 0;
        }
    }
    sb_append(&sb, ")$");
    return sb.data;
}

