#include <ctype.h>
#include <stdarg.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "log.h"
#include "util.h"

void *xmalloc(size_t size) {
    void *p = malloc(size ? size : 1);
    if (p == NULL) {
        fatal("Memory allocation failed.");
    }
    return p;
}

void *xrealloc(void *ptr, size_t size) {
    void *p = realloc(ptr, size ? size : 1);
    if (p == NULL) {
        fatal("Memory allocation failed.");
    }
    return p;
}

void *xcalloc(size_t count, size_t size) {
    void *p = calloc(count ? count : 1, size ? size : 1);
    if (p == NULL) {
        fatal("Memory allocation failed.");
    }
    return p;
}

char *xstrdup(const char *s) {
    char *p = strdup(s);
    if (p == NULL) {
        fatal("Memory allocation failed.");
    }
    return p;
}

char *xstrndup(const char *s, size_t n) {
    char *p = strndup(s, n);
    if (p == NULL) {
        fatal("Memory allocation failed.");
    }
    return p;
}

char *xasprintf(const char *fmt, ...) {
    va_list ap;
    char *out = NULL;
    va_start(ap, fmt);
    if (vasprintf(&out, fmt, ap) < 0) {
        fatal("Memory allocation failed.");
    }
    va_end(ap);
    return out;
}

void sb_init(strbuf_t *sb) {
    sb->cap = 64;
    sb->len = 0;
    sb->data = xmalloc(sb->cap);
    sb->data[0] = '\0';
}

void sb_append(strbuf_t *sb, const char *s) {
    size_t n = strlen(s);
    if (sb->len + n + 1 > sb->cap) {
        while (sb->len + n + 1 > sb->cap) {
            sb->cap *= 2;
        }
        sb->data = xrealloc(sb->data, sb->cap);
    }
    memcpy(sb->data + sb->len, s, n + 1);
    sb->len += n;
}

/* Heuristic used to decide whether a buffer looks like binary data. */
int is_binary_buf(const unsigned char *buf, size_t len) {
    size_t limit;
    size_t odd = 0;
    size_t i;

    if (len == 0) {
        return 0;
    }
    if (len >= 3 && buf[0] == 0xEF && buf[1] == 0xBB && buf[2] == 0xBF) {
        return 0; /* UTF-8 byte order mark */
    }
    if (len >= 5 && memcmp(buf, "%PDF-", 5) == 0) {
        return 1;
    }

    limit = len > 512 ? 512 : len;
    for (i = 0; i < limit; i++) {
        unsigned char c = buf[i];
        if (c == 0) {
            return 1;
        }
        if ((c < 7 || c > 14) && (c < 32 || c > 127)) {
            if (c > 193 && c < 224 && i + 1 < limit) {
                i++;
                if (buf[i] > 127 && buf[i] < 192) {
                    continue;
                }
            } else if (c > 223 && c < 240 && i + 2 < limit) {
                i++;
                if (buf[i] > 127 && buf[i] < 192 && buf[i + 1] > 127 && buf[i + 1] < 192) {
                    i++;
                    continue;
                }
            }
            odd++;
            if (i >= 32 && (odd * 100) / limit > 10) {
                return 1;
            }
        }
    }
    return (odd * 100) / limit > 10;
}

int has_regex_chars(const char *q) {
    return strpbrk(q, "$()*+.?[\\^{|") != NULL;
}

int has_fnmatch_chars(const char *p) {
    return strpbrk(p, "!*?[]") != NULL;
}

int all_lowercase(const char *s) {
    for (; *s; s++) {
        if (!isascii((unsigned char)*s) || isupper((unsigned char)*s)) {
            return 0;
        }
    }
    return 1;
}

int word_char(char c) {
    return isalnum((unsigned char)c) || c == '_';
}

const char *literal_find(const char *hay, size_t hay_len, const char *needle, size_t needle_len, int icase) {
    size_t i, j;
    if (needle_len == 0) {
        return hay;
    }
    if (hay_len < needle_len) {
        return NULL;
    }
    if (!icase) {
        return memmem(hay, hay_len, needle, needle_len);
    }
    for (i = 0; i + needle_len <= hay_len; i++) {
        if ((char)tolower((unsigned char)hay[i]) != needle[0]) {
            continue;
        }
        for (j = 1; j < needle_len; j++) {
            if ((char)tolower((unsigned char)hay[i + j]) != needle[j]) {
                break;
            }
        }
        if (j == needle_len) {
            return hay + i;
        }
    }
    return NULL;
}

int sorted_find(const char *key, char *const *arr, size_t len) {
    size_t lo = 0, hi = len;
    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2;
        int rc = strcmp(key, arr[mid]);
        if (rc < 0) {
            hi = mid;
        } else if (rc > 0) {
            lo = mid + 1;
        } else {
            return (int)mid;
        }
    }
    return -1;
}

size_t next_line(const char **line, const char *buf, size_t buf_len, size_t offset) {
    const char *p = buf + offset;
    const char *end = buf + buf_len;
    size_t n = 0;
    while (p < end && *p != '\n') {
        p++;
        n++;
    }
    *line = buf + offset;
    return n;
}

/* Replace the list of matches with the regions between them (whole lines). */
size_t invert_match_list(const char *buf, size_t buf_len, match_t *matches, size_t matches_len) {
    size_t i;
    size_t read_idx = 0;
    size_t out_count = 0;
    size_t region_start = 0;
    size_t last_line_end = 0;
    int in_region = 1;
    match_t next;

    log_debug("Inverting %lu matches.", (unsigned long)matches_len);

    if (matches_len == 0) {
        matches[0].start = 0;
        matches[0].end = buf_len - 1;
        return 1;
    }
    next = matches[0];

    for (i = 0; i < buf_len; i++) {
        if (i == next.start) {
            i = next.end - 1;
            read_idx++;
            if (read_idx < matches_len) {
                next = matches[read_idx];
            }
            if (in_region && last_line_end > region_start) {
                matches[out_count].start = region_start;
                matches[out_count].end = last_line_end - 1;
                out_count++;
            }
            in_region = 0;
        } else if (i == buf_len - 1 && in_region) {
            matches[out_count].start = region_start;
            matches[out_count].end = i;
            out_count++;
        } else if (buf[i] == '\n') {
            last_line_end = i + 1;
            if (!in_region) {
                region_start = last_line_end;
            }
            in_region = 1;
        }
    }

    for (i = 0; i < out_count; i++) {
        log_debug("Inverted match %lu start %lu end %lu.", (unsigned long)i, (unsigned long)matches[i].start, (unsigned long)matches[i].end);
    }
    return out_count;
}

void grow_matches(match_t **matches, size_t *cap, size_t needed) {
    if (needed < *cap) {
        return;
    }
    *cap = *matches ? *cap * 2 : 100;
    *matches = xrealloc(*matches, *cap * sizeof(match_t));
}
