cat > log.c <<'EOF'
#include <stdarg.h>
#include <stdio.h>
#include <stdlib.h>

#include "log.h"
#include "options.h"

static int threshold = LVL_ERR;

void set_log_level(int level) {
    threshold = level;
}

int debug_enabled(void) {
    return threshold <= LVL_DEBUG;
}

static void emit(int level, const char *fmt, va_list ap) {
    FILE *f;
    if (level < threshold) {
        return;
    }
    if (level == LVL_ERR) {
