        { "search-binary", no_argument, &opts.search_binary_files, 1 },
        { "search-files", no_argument, &opts.search_stream, 0 },
        { "search-zip", no_argument, &opts.search_zip_files, 1 },
        { "silent", no_argument, NULL, 0 },
        { "skip-vcs-ignores", no_argument, NULL, 'U' },
        { "smart-case", no_argument, NULL, 'S' },
        { "stats", no_argument, &opts.stats, 1 },
        { "stats-only", no_argument, NULL, 0 },
        { "unrestricted", no_argument, NULL, 'u' },
        { "version", no_argument, &version, 1 },
        { "vimgrep", no_argument, &opts.vimgrep, 1 },
        { "width", required_argument, NULL, 'W' },
        { "word-regexp", no_argument, NULL, 'w' },
        { "workers", required_argument, NULL, 0 },
    };

    init_options();

    base_count = sizeof(base_longopts) / sizeof(base_longopts[0]);
    total = base_count + langs_len + 1;
    longopts = xcalloc(total, sizeof(struct option));
    memcpy(longopts, base_longopts, sizeof(base_longopts));
    for (k = 0; k < langs_len; k++) {
        longopts[base_count + k].name = langs[k].name;
        longopts[base_count + k].has_arg = no_argument;
        longopts[base_count + k].flag = NULL;
        longopts[base_count + k].val = 0;
    }
    chosen_langs = xcalloc(langs_len + 1, sizeof(size_t));

    if (fstat(fileno(stdin), &statbuf) == 0) {
        if (S_ISFIFO(statbuf.st_mode) || S_ISREG(statbuf.st_mode)) {
            opts.search_stream = 1;
        }
    }

    if (!isatty(fileno(stdout))) {
        opts.color = 0;
        group = 0;
        if (fstat(fileno(stdout), &statbuf) != 0) {
            fatal("Error fstat()ing stdout");
        }
        opts.stdout_inode = statbuf.st_ino;
    }

    while ((ch = getopt_long(argc, argv, "A:aB:C:cDG:g:FfHhiLlm:nop:QRrSsvVtuUwW:z0", longopts, &opt_index)) != -1) {
        switch (ch) {
            case 'A':
                if (optarg) {
                    if (parse_len(optarg, &num)) {
                        opts.after = (size_t)num;
                    } else {
                        optind--;
                        opts.after = DEFAULT_AFTER_LEN;
                    }
                } else {
                    opts.after = DEFAULT_AFTER_LEN;
                }
                break;
            case 'a':
                opts.search_all_files = 1;
                opts.search_binary_files = 1;
                break;
            case 'B':
                if (optarg) {
                    if (parse_len(optarg, &num)) {
                        opts.before = (size_t)num;
                    } else {
                        optind--;
                        opts.before = DEFAULT_BEFORE_LEN;
                    }
                } else {
                    opts.before = DEFAULT_BEFORE_LEN;
                }
                break;
            case 'C':
                if (optarg) {
                    if (parse_len(optarg, &num)) {
                        opts.context = (int)num;
                    } else {
                        optind--;
                        opts.context = DEFAULT_CONTEXT_LEN;
                    }
                } else {
                    opts.context = DEFAULT_CONTEXT_LEN;
                }
                break;
            case 'c':
                opts.print_count = 1;
                opts.print_filename_only = 1;
                break;
            case 'D':
                set_log_level(LVL_DEBUG);
                break;
            case 'f':
                opts.follow_symlinks = 1;
                break;
            case 'g':
                needs_query = 0;
                accepts_query = 0;
                opts.match_files = 1;
                /* fall through */
            case 'G':
                if (file_search_regex) {
                    usage();
                    fflush(stdout);
                    log_err("File search regex (-g or -G) already specified.");
                    exit(1);
                }
                file_search_regex = xstrdup(optarg);
                break;
            case 'H':
                opts.print_path = PATH_PRINT_TOP;
                break;
            case 'h':
                help = 1;
                break;
            case 'i':
                opts.casing = CASE_INSENSITIVE;
                break;
            case 'L':
                opts.print_nonmatching_files = 1;
                opts.print_path = PATH_PRINT_TOP;
                break;
            case 'l':
                needs_query = 0;
                opts.print_filename_only = 1;
                opts.print_path = PATH_PRINT_TOP;
                break;
            case 'm':
                opts.max_matches_per_file = (size_t)atoi(optarg);
                break;
            case 'n':
                opts.recurse_dirs = 0;
                break;
            case 'p':
                opts.path_to_ignore = 1;
                load_ignore_patterns(root_ignores, optarg);
                break;
            case 'o':
                opts.only_matching = 1;
                break;
            case 'F':
            case 'Q':
                opts.literal = 1;
                break;
            case 'R':
            case 'r':
                opts.recurse_dirs = 1;
                break;
            case 'S':
                opts.casing = CASE_SMART;
                break;
            case 's':
                opts.casing = CASE_SENSITIVE;
                break;
            case 't':
                opts.search_all_files = 1;
                break;
            case 'u':
                opts.search_binary_files = 1;
                opts.search_all_files = 1;
                opts.search_hidden_files = 1;
                break;
            case 'U':
                opts.skip_vcs_ignores = 1;
                break;
            case 'v':
                opts.invert_match = 1;
                break;
            case 'V':
                version = 1;
                break;
            case 'w':
                opts.word_regexp = 1;
                break;
            case 'W': {
                char *end;
                errno = 0;
                num = strtol(optarg, &end, 10);
                if (end == optarg || *end != '\0' || errno == ERANGE) {
                    fatal("Invalid width\n");
                }
                opts.width = (size_t)num;
                break;
            }
            case 'z':
                opts.search_zip_files = 1;
                break;
            case '0':
                opts.path_sep = '\0';
                break;
            case 0: {
                const char *name = longopts[opt_index].name;
                if (strcmp(name, "ackmate-dir-filter") == 0) {
                    compile_regex(&opts.ackmate_dir_filter, NULL, optarg, 0, 0);
                    break;
                } else if (strcmp(name, "depth") == 0) {
                    opts.max_search_depth = atoi(optarg);
                    break;
                } else if (strcmp(name, "filename") == 0) {
                    opts.print_path = PATH_PRINT_DEFAULT;
                    opts.print_line_numbers = 1;
                    break;
                } else if (strcmp(name, "ignore-dir") == 0 || strcmp(name, "ignore") == 0) {
                    add_ignore_pattern(root_ignores, optarg);
                    break;
                } else if (strcmp(name, "no-filename") == 0 || strcmp(name, "nofilename") == 0) {
                    opts.print_path = PATH_PRINT_NOTHING;
                    opts.print_line_numbers = 0;
                    break;
                } else if (strcmp(name, "no-pager") == 0 || strcmp(name, "nopager") == 0) {
                    free(opts.pager);
                    opts.pager = NULL;
                    break;
                } else if (strcmp(name, "pager") == 0) {
                    free(opts.pager);
                    opts.pager = xstrdup(optarg);
                    break;
                } else if (strcmp(name, "print-all-files") == 0) {
                    opts.print_all_paths = 1;
                    break;
                } else if (strcmp(name, "workers") == 0) {
                    opts.workers = atoi(optarg);
                    break;
                } else if (strcmp(name, "color-line-number") == 0) {
                    color_option(&opts.color_line_number, optarg);
                    break;
                } else if (strcmp(name, "color-match") == 0) {
                    color_option(&opts.color_match, optarg);
                    break;
                } else if (strcmp(name, "color-path") == 0) {
                    color_option(&opts.color_path, optarg);
                    break;
                } else if (strcmp(name, "silent") == 0) {
                    set_log_level(LVL_NONE);
                    break;
                } else if (strcmp(name, "stats-only") == 0) {
                    opts.print_filename_only = 1;
                    opts.print_path = PATH_PRINT_NOTHING;
                    opts.stats = 1;
                    break;
                }

                if (longopts[opt_index].flag != NULL) {
                    break;
                }

                for (k = 0; k < langs_len; k++) {
                    if (strcmp(name, langs[k].name) == 0) {
                        has_filetype = 1;
                        chosen_langs[chosen_len++] = k;
                        break;
                    }
                }
                if (k != langs_len) {
                    break;
                }

                log_err("option %s does not take a value", name);
                /* fall through */
            }
            default:
                usage();
                exit(1);
        }
    }

    if (help) {
        usage();
        exit(0);
    }

    if (version) {
        print_version();
        exit(0);
    }

    if (list_file_types) {
        print_lang_list();
        exit(0);
    }

    if (home_dir && !opts.search_all_files) {
        char *agignore;
        log_debug("Found user's home dir: %s", home_dir);
        agignore = xasprintf("%s/.agignore", home_dir);
        load_ignore_patterns(root_ignores, agignore);
        free(agignore);
    }

    if (!opts.skip_vcs_ignores) {
        FILE *gc = popen("git config -z --path --get core.excludesfile 2>/dev/null", "r");
        if (gc != NULL) {
            char *res = NULL;
            size_t len = 0;
            do {
                res = xrealloc(res, len + 65);
                len += fread(res + len, 1, 64, gc);
            } while (!feof(gc) && len > 0 && len % 64 == 0);
            res[len] = '\0';
            if (len == 0) {
                const char *xdg = getenv("XDG_CONFIG_HOME");
                free(res);
                if (xdg) {
                    res = xasprintf("%s/%s", xdg, "git/ignore");
                } else if (home_dir) {
                    res = xasprintf("%s/%s", home_dir, ".config/git/ignore");
                } else {
                    res = xstrdup("");
                }
            }
            log_debug("global core.excludesfile: %s", res);
            load_ignore_patterns(root_ignores, res);
            free(res);
            pclose(gc);
        }
    }

    if (file_search_regex) {
        int fopts = 0;
        if (opts.casing == CASE_INSENSITIVE || (opts.casing == CASE_SMART && all_lowercase(file_search_regex))) {
            fopts |= PCRE_CASELESS;
        }
        if (opts.word_regexp) {
            char *wrapped = xasprintf("\\b%s\\b", file_search_regex);
            free(file_search_regex);
            file_search_regex = wrapped;
        }
        compile_regex(&opts.file_search_regex, &opts.file_search_regex_extra, file_search_regex, fopts, 0);
        free(file_search_regex);
        file_search_regex = NULL;
    }

    if (has_filetype) {
        char *lang_re = build_lang_regex(chosen_langs, chosen_len);
        compile_regex(&opts.file_search_regex, &opts.file_search_regex_extra, lang_re, 0, 0);
        free(lang_re);
    }
    free(chosen_langs);

    if (opts.pager) {
        out_fd = popen(opts.pager, "w");
        if (!out_fd) {
            perror("Failed to run pager");
            exit(1);
        }
    }

    argc -= optind;
    argv += optind;

    if (needs_query && argc == 0) {
        log_err("What do you want to search for?");
        exit(1);
    }

    if (accepts_query && argc > 0) {
        if (!needs_query && argv[0][0] == '\0') {
            opts.query = xstrdup(".");
        } else {
            opts.query = xstrdup(argv[0]);
        }
        argc--;
        argv++;
    } else if (!needs_query) {
        opts.query = xstrdup(".");
    }
    opts.query_len = (int)strlen(opts.query);

    log_debug("Query is %s", opts.query);

    if (opts.query_len == 0) {
        log_err("Error: No query. What do you want to search for?");
        exit(1);
    }

    if (!has_regex_chars(opts.query)) {
        opts.literal = 1;
    }

    if (opts.context > 0) {
        opts.before = (size_t)opts.context;
        opts.after = (size_t)opts.context;
    }

    if (opts.ackmate) {
        opts.color = 0;
        opts.print_break = 1;
        group = 1;
        opts.search_stream = 0;
    }

    if (opts.vimgrep) {
        opts.color = 0;
        opts.print_break = 0;
        group = 1;
        opts.search_stream = 0;
        opts.print_path = PATH_PRINT_NOTHING;
    }

    if (opts.parallel) {
        opts.search_stream = 0;
    }

    if (opts.print_path == PATH_PRINT_DEFAULT && opts.print_break) {
        if (!group) {
            opts.print_path = PATH_PRINT_DEFAULT_EACH_LINE;
            opts.print_break = 0;
        }
    }

    if (argc > 0) {
        *paths = xcalloc((size_t)argc + 1, sizeof(char *));
        *base_paths = xcalloc((size_t)argc + 1, sizeof(char *));
        opts.search_stream = 0;
        for (i = 0; i < argc; i++) {
            char *path = xstrdup(argv[i]);
            size_t plen = strlen(path);
            char *real;
            if (plen > 1 && path[plen - 1] == '/') {
                path[plen - 1] = '\0';
            }
            (*paths)[i] = path;
            real = realpath(path, NULL);
            if (real) {
                (*base_paths)[i] = xasprintf("%s/", real);
                free(real);
            } else {
                (*base_paths)[i] = NULL;
            }
        }
        opts.paths_len = argc;
    } else {
        char *cwd = getcwd(NULL, 0);
        *paths = xcalloc(2, sizeof(char *));
        *base_paths = xcalloc(2, sizeof(char *));
        (*paths)[0] = xstrdup(".");
        (*base_paths)[0] = cwd ? xstrdup(cwd) : NULL;
        free(cwd);
        opts.paths_len = 1;
    }

    free(longopts);
}
EOF
echo ok"}

actions.command:
cd /workspace/src && cat > options.c <<'EOF'
#include <ctype.h>
#include <errno.h>
#include <getopt.h>
#include <limits.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>

#include "ignore.h"
#include "lang.h"
#include "log.h"
#include "options.h"
#include "util.h"

cli_options opts;
FILE *out_fd = NULL;

static const char *const color_match_default = "\033[30;43m";
static const char *const color_line_default = "\033[1;33m";
static const char *const color_path_default = "\033[1;32m";

void usage(void) {
    fputs(usage_text, stdout);
}

void print_version(void) {
    printf("ag version 2.2.0\n\n");
    printf("Features:\n");
    printf("  +jit +lzma +zlib\n");
}

void init_options(void) {
    memset(&opts, 0, sizeof(opts));
    opts.casing = CASE_SMART;
    opts.color = 1;
    opts.color_match = xstrdup(color_match_default);
    opts.color_line_number = xstrdup(color_line_default);
    opts.color_path = xstrdup(color_path_default);
    opts.max_search_depth = DEFAULT_MAX_SEARCH_DEPTH;
    opts.mmap = 1;
    opts.multiline = 1;
    opts.path_sep = '\n';
    opts.print_break = 1;
    opts.print_path = PATH_PRINT_DEFAULT;
    opts.print_line_numbers = 1;
    opts.recurse_dirs = 1;
    opts.use_thread_affinity = 1;
}

void cleanup_options(void) {
    free(opts.color_match);
    free(opts.color_line_number);
    free(opts.color_path);
    free(opts.query);
    free(opts.pager);
}

void compile_regex(pcre **re, pcre_extra **extra, const char *pattern, int pcre_opts, int study_opts) {
    const char *err = NULL;
    int err_off = 0;

    *re = pcre_compile(pattern, pcre_opts, &err, &err_off, NULL);
    if (*re == NULL) {
        fatal("Bad regex! pcre_compile() failed at position %i: %s\nIf you meant to search for a literal string, run ag with -Q",
              err_off, err);
    }
    if (extra != NULL) {
        *extra = pcre_study(*re, study_opts, &err);
        if (*extra == NULL) {
            log_debug("pcre_study returned nothing useful. Error: %s", err);
        }
    }
}

/* Parse a context length argument. Returns 0 if the argument isn't a number. */
static int parse_len(const char *arg, long *out) {
    char *end;
    errno = 0;
    *out = strtol(arg, &end, 10);
    if (end == arg || *end != '\0' || errno == ERANGE) {
        return 0;
    }
    return 1;
}

static void color_option(char **slot, const char *arg) {
    free(*slot);
    *slot = xasprintf("\033[%sm", arg);
}

void parse_options(int argc, char **argv, char **base_paths[], char **paths[]) {
    int ch;
    int i;
    int useless = 0;
    int group = 1;
    int help = 0;
    int version = 0;
    int list_file_types = 0;
    int opt_index = 0;
    long num;
    const char *home_dir = getenv("HOME");
    int accepts_query = 1;
    int needs_query = 1;
    struct stat statbuf;
    char *file_search_regex = NULL;
    size_t *chosen_langs = NULL;
    size_t chosen_len = 0;
    int has_filetype = 0;
    size_t base_count, total, k;
    struct option *longopts;

    struct option base_longopts[] = {
        { "ackmate", no_argument, &opts.ackmate, 1 },
        { "ackmate-dir-filter", required_argument, NULL, 0 },
        { "affinity", no_argument, &opts.use_thread_affinity, 1 },
        { "after", optional_argument, NULL, 'A' },
        { "all-text", no_argument, NULL, 't' },
        { "all-types", no_argument, NULL, 'a' },
        { "before", optional_argument, NULL, 'B' },
        { "break", no_argument, &opts.print_break, 1 },
        { "case-sensitive", no_argument, NULL, 's' },
        { "color", no_argument, &opts.color, 1 },
        { "color-line-number", required_argument, NULL, 0 },
        { "color-match", required_argument, NULL, 0 },
        { "color-path", required_argument, NULL, 0 },
        { "color-win-ansi", no_argument, &opts.color_win_ansi, 1 },
        { "column", no_argument, &opts.column, 1 },
        { "context", optional_argument, NULL, 'C' },
        { "count", no_argument, NULL, 'c' },
        { "debug", no_argument, NULL, 'D' },
        { "depth", required_argument, NULL, 0 },
        { "filename", no_argument, NULL, 0 },
        { "filename-pattern", required_argument, NULL, 'g' },
        { "file-search-regex", required_argument, NULL, 'G' },
        { "files-with-matches", no_argument, NULL, 'l' },
        { "files-without-matches", no_argument, NULL, 'L' },
        { "fixed-strings", no_argument, NULL, 'F' },
        { "follow", no_argument, &opts.follow_symlinks, 1 },
        { "group", no_argument, &group, 1 },
        { "heading", no_argument, &opts.print_path, PATH_PRINT_TOP },
        { "help", no_argument, NULL, 'h' },
        { "hidden", no_argument, &opts.search_hidden_files, 1 },
        { "ignore", required_argument, NULL, 0 },
        { "ignore-case", no_argument, NULL, 'i' },
        { "ignore-dir", required_argument, NULL, 0 },
        { "invert-match", no_argument, NULL, 'v' },
        { "line-numbers", no_argument, &opts.print_line_numbers, 2 },
        { "list-file-types", no_argument, &list_file_types, 1 },
        { "literal", no_argument, NULL, 'Q' },
        { "match", no_argument, &useless, 0 },
        { "max-count", required_argument, NULL, 'm' },
        { "mmap", no_argument, &opts.mmap, 1 },
        { "multiline", no_argument, &opts.multiline, 1 },
        { "no-affinity", no_argument, &opts.use_thread_affinity, 0 },
        { "noaffinity", no_argument, &opts.use_thread_affinity, 0 },
        { "no-break", no_argument, &opts.print_break, 0 },
        { "nobreak", no_argument, &opts.print_break, 0 },
        { "no-color", no_argument, &opts.color, 0 },
        { "nocolor", no_argument, &opts.color, 0 },
        { "no-filename", no_argument, NULL, 0 },
        { "nofilename", no_argument, NULL, 0 },
        { "no-follow", no_argument, &opts.follow_symlinks, 0 },
        { "nofollow", no_argument, &opts.follow_symlinks, 0 },
        { "no-group", no_argument, &group, 0 },
        { "nogroup", no_argument, &group, 0 },
        { "no-heading", no_argument, &opts.print_path, PATH_PRINT_EACH_LINE },
        { "noheading", no_argument, &opts.print_path, PATH_PRINT_EACH_LINE },
        { "no-mmap", no_argument, &opts.mmap, 0 },
        { "nommap", no_argument, &opts.mmap, 0 },
        { "no-multiline", no_argument, &opts.multiline, 0 },
        { "nomultiline", no_argument, &opts.multiline, 0 },
        { "no-numbers", no_argument, &opts.print_line_numbers, 0 },
        { "nonumbers", no_argument, &opts.print_line_numbers, 0 },
        { "no-pager", no_argument, NULL, 0 },
        { "nopager", no_argument, NULL, 0 },
        { "no-recurse", no_argument, NULL, 'n' },
        { "norecurse", no_argument, NULL, 'n' },
        { "null", no_argument, NULL, '0' },
        { "numbers", no_argument, &opts.print_line_numbers, 2 },
        { "only-matching", no_argument, NULL, 'o' },
        { "one-device", no_argument, &opts.one_dev, 1 },
        { "pager", required_argument, NULL, 0 },
        { "parallel", no_argument, &opts.parallel, 1 },
        { "passthrough", no_argument, &opts.passthrough, 1 },
        { "passthru", no_argument, &opts.passthrough, 1 },
        { "path-to-ignore", required_argument, NULL, 'p' },
        { "print0", no_argument, NULL, '0' },
        { "print-all-files", no_argument, NULL, 0 },
        { "print-long-lines", no_argument, &opts.print_long_lines, 1 },
        { "recurse", no_argument, NULL, 'r' },
        { "search-binary", no_argument, &opts.search_binary_files, 1 },
        { "search-files", no_argument, &opts.search_stream, 0 },
        { "search-zip", no_argument, &opts.search_zip_files, 1 },
        { "silent", no_argument, NULL, 0 },
        { "skip-vcs-ignores", no_argument, NULL, 'U' },
        { "smart-case", no_argument, NULL, 'S' },
        { "stats", no_argument, &opts.stats, 1 },
        { "stats-only", no_argument, NULL, 0 },
        { "unrestricted", no_argument, NULL, 'u' },
        { "version", no_argument, &version, 1 },
        { "vimgrep", no_argument, &opts.vimgrep, 1 },
        { "width", required_argument, NULL, 'W' },
        { "word-regexp", no_argument, NULL, 'w' },
        { "workers", required_argument, NULL, 0 },
    };

    init_options();

    base_count = sizeof(base_longopts) / sizeof(base_longopts[0]);
    total = base_count + langs_len + 1;
    longopts = xcalloc(total, sizeof(struct option));
    memcpy(longopts, base_longopts, sizeof(base_longopts));
    for (k = 0; k < langs_len; k++) {
        longopts[base_count + k].name = langs[k].name;
        longopts[base_count + k].has_arg = no_argument;
        longopts[base_count + k].flag = NULL;
        longopts[base_count + k].val = 0;
    }
    chosen_langs = xcalloc(langs_len + 1, sizeof(size_t));

    if (fstat(fileno(stdin), &statbuf) == 0) {
        if (S_ISFIFO(statbuf.st_mode) || S_ISREG(statbuf.st_mode)) {
            opts.search_stream = 1;
        }
    }

    if (!isatty(fileno(stdout))) {
        opts.color = 0;
        group = 0;
        if (fstat(fileno(stdout), &statbuf) != 0) {
            fatal("Error fstat()ing stdout");
        }
        opts.stdout_inode = statbuf.st_ino;
    }

