static const char *const always_skip[] = { ".", "..", NULL };

static const int fnmatch_flags = FNM_PATHNAME;

static int ig_is_empty(const ignores *ig) {
    return ig->extensions_len + ig->names_len + ig->slash_names_len + ig->regexes_len + ig->slash_regexes_len == 0;
}

ignores *init_ignore(ignores *parent, const char *dirname, size_t dirname_len) {
    ignores *ig = xcalloc(1, sizeof(ignores));
    ig->dirname = dirname;
    ig->dirname_len = dirname_len;

    if (parent && ig_is_empty(parent) && parent->parent) {
        ig->parent = parent->parent;
    } else {
        ig->parent = parent;
    }

    if (parent && parent->abs_path_len > 0) {
        ig->abs_path = xasprintf("%s/%s", parent->abs_path, dirname);
        ig->abs_path_len = parent->abs_path_len + 1 + dirname_len;
    } else if (dirname_len == 1 && dirname[0] == '.') {
        ig->abs_path = xstrdup("");
        ig->abs_path_len = 0;
    } else {
        ig->abs_path = xstrdup(dirname);
        ig->abs_path_len = dirname_len;
    }
    return ig;
}

static void free_list(char **list, size_t len) {
    size_t i;
    for (i = 0; i < len; i++) {
        free(list[i]);
    }
    free(list);
}

void cleanup_ignore(ignores *ig) {
    if (ig == NULL) {
        return;
    }
    free_list(ig->extensions, ig->extensions_len);
    free_list(ig->names, ig->names_len);
    free_list(ig->slash_names, ig->slash_names_len);
    free_list(ig->regexes, ig->regexes_len);
    free_list(ig->invert_regexes, ig->invert_regexes_len);
    free_list(ig->slash_regexes, ig->slash_regexes_len);
    free(ig->abs_path);
    free(ig);
}

/* Insert into a sorted list, keeping it sorted. */
static void sorted_insert(char ***list, size_t *len, const char *pattern, size_t pattern_len) {
    size_t i;
    char **arr;
    char *copy = xstrndup(pattern, pattern_len);

    (*len)++;
    arr = xrealloc(*list, (*len) * sizeof(char *));
    *list = arr;
    for (i = *len - 1; i > 0; i--) {
        if (strcmp(copy, arr[i - 1]) > 0) {
            break;
        }
        arr[i] = arr[i - 1];
    }
    arr[i] = copy;
}

void add_ignore_pattern(ignores *ig, const char *pattern) {
    size_t pattern_len;
    char ***list;
    size_t *list_len;

    if (strncmp(pattern, "./", 2) == 0) {
        pattern += 2;
    }

    for (pattern_len = strlen(pattern); pattern_len > 0; pattern_len--) {
        if (!isspace((unsigned char)pattern[pattern_len - 1])) {
            break;
        }
    }

    if (pattern_len == 0) {
        log_debug("Pattern is empty. Not adding any ignores.");
        return;
    }

    if (has_fnmatch_chars(pattern)) {
        if (pattern[0] == '*' && pattern[1] == '.' && strchr(pattern + 2, '.') && !has_fnmatch_chars(pattern + 2)) {
            list = &ig->extensions;
            list_len = &ig->extensions_len;
            pattern += 2;
            pattern_len -= 2;
        } else if (pattern[0] == '/') {
            list = &ig->slash_regexes;
            list_len = &ig->slash_regexes_len;
            pattern++;
            pattern_len--;
        } else if (pattern[0] == '!') {
            list = &ig->invert_regexes;
            list_len = &ig->invert_regexes_len;
            pattern++;
            pattern_len--;
        } else {
            list = &ig->regexes;
            list_len = &ig->regexes_len;
        }
    } else {
        if (pattern[0] == '/') {
            list = &ig->slash_names;
            list_len = &ig->slash_names_len;
            pattern++;
            pattern_len--;
        } else {
            list = &ig->names;
            list_len = &ig->names_len;
        }
    }

    sorted_insert(list, list_len, pattern, pattern_len);
    log_debug("added ignore pattern %s to %s", pattern, ig == root_ignores ? "root ignores" : ig->abs_path);
}

void load_ignore_patterns(ignores *ig, const char *path) {
    FILE *fp;
    char *line = NULL;
    size_t cap = 0;
    ssize_t len;

    fp = fopen(path, "r");
    if (fp == NULL) {
        log_debug("Skipping ignore file %s: not readable", path);
        return;
    }
    log_debug("Loading ignore file %s.", path);

    while ((len = getline(&line, &cap, fp)) > 0) {
        if (line[0] == '\n' || line[0] == '#') {
            continue;
        }
        if (line[len - 1] == '\n') {
            line[len - 1] = '\0';
        }
        add_ignore_pattern(ig, line);
    }

    free(line);
    fclose(fp);
}

static int ackmate_dir_match(const char *dir_name) {
    if (opts.ackmate_dir_filter == NULL) {
        return 0;
    }
    /* Non-zero when the filter does NOT match. */
    return pcre_exec(opts.ackmate_dir_filter, NULL, dir_name, (int)strlen(dir_name), 0, 0, NULL, 0) != 0;
}

static int path_ignore_search(const ignores *ig, const char *path, const char *filename) {
    char *temp;
    const char *cmp;
    size_t i;
    int pos;
    int rv;

    pos = sorted_find(filename, ig->names, ig->names_len);
    if (pos >= 0) {
        log_debug("file %s ignored because name matches static pattern %s", filename, ig->names[pos]);
        return 1;
    }

    temp = xasprintf("%s/%s", path[0] == '.' ? path + 1 : path, filename);
    cmp = temp[0] == '/' ? temp + 1 : temp;

    if (strncmp(cmp, ig->abs_path, ig->abs_path_len) == 0) {
        const char *slash_filename = cmp + ig->abs_path_len;
        if (slash_filename[0] == '/') {
            slash_filename++;
        }

        pos = sorted_find(slash_filename, ig->names, ig->names_len);
        if (pos >= 0) {
            log_debug("file %s ignored because name matches static pattern %s", temp, ig->names[pos]);
            free(temp);
            return 1;
        }

        pos = sorted_find(slash_filename, ig->slash_names, ig->slash_names_len);
        if (pos >= 0) {
            log_debug("file %s ignored because name matches slash static pattern %s", slash_filename, ig->slash_names[pos]);
            free(temp);
            return 1;
        }

        for (i = 0; i < ig->names_len; i++) {
            const char *hit = strstr(slash_filename, ig->names[i]);
            if (hit == slash_filename || (hit && *(hit - 1) == '/')) {
                hit += strlen(ig->names[i]);
                if (*hit == '\0' || *hit == '/') {
                    log_debug("file %s ignored because path somewhere matches name %s", slash_filename, ig->names[i]);
                    free(temp);
                    return 1;
                }
            }
            log_debug("pattern %s doesn't match path %s", ig->names[i], slash_filename);
        }

        for (i = 0; i < ig->slash_regexes_len; i++) {
            if (fnmatch(ig->slash_regexes[i], slash_filename, fnmatch_flags) == 0) {
                log_debug("file %s ignored because name matches slash regex pattern %s", slash_filename, ig->slash_regexes[i]);
                free(temp);
                return 1;
            }
            log_debug("pattern %s doesn't match slash file %s", ig->slash_regexes[i], slash_filename);
        }
    }

    for (i = 0; i < ig->invert_regexes_len; i++) {
        if (fnmatch(ig->invert_regexes[i], filename, fnmatch_flags) == 0) {
            log_debug("file %s not ignored because name matches regex pattern !%s", filename, ig->invert_regexes[i]);
            free(temp);
            return 0;
        }
        log_debug("pattern !%s doesn't match file %s", ig->invert_regexes[i], filename);
    }

    for (i = 0; i < ig->regexes_len; i++) {
        if (fnmatch(ig->regexes[i], filename, fnmatch_flags) == 0) {
            log_debug("file %s ignored because name matches regex pattern %s", filename, ig->regexes[i]);
            free(temp);
            return 1;
        }
        log_debug("pattern %s doesn't match file %s", ig->regexes[i], filename);
    }

    rv = ackmate_dir_match(temp);
    free(temp);
    return rv;
}

static int stat_entry(const char *path, const struct dirent *d, struct stat *st, int follow) {
    char *full = xasprintf("%s/%s", path, d->d_name);
    int rc = follow ? stat(full, st) : lstat(full, st);
    free(full);
    return rc;
}

int entry_is_directory(const char *path, const struct dirent *d) {
    struct stat st;
    if (d->d_type != DT_UNKNOWN && d->d_type != DT_LNK) {
        return d->d_type == DT_DIR;
    }
    if (stat_entry(path, d, &st, 1) != 0) {
        return 0;
    }
    return S_ISDIR(st.st_mode);
}

int entry_is_symlink(const char *path, const struct dirent *d) {
    struct stat st;
    if (d->d_type != DT_UNKNOWN) {
        return d->d_type == DT_LNK;
    }
    if (stat_entry(path, d, &st, 0) != 0) {
        return 0;
    }
    return S_ISLNK(st.st_mode);
}

int entry_is_named_pipe(const char *path, const struct dirent *d) {
    struct stat st;
    if (d->d_type != DT_UNKNOWN) {
        return d->d_type == DT_FIFO || d->d_type == DT_SOCK;
    }
    if (stat_entry(path, d, &st, 1) != 0) {
        return 0;
    }
    return S_ISFIFO(st.st_mode) || S_ISSOCK(st.st_mode);
}

