cat > search.c <<'EOF'
#include <dirent.h>
#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>

#include "ignore.h"
#include "log.h"
#include "options.h"
#include "print.h"
#include "search.h"
#include "util.h"
#include "zfile.h"

search_stats_t stats;

/* ---- queue of files found while walking directories ---- */

typedef struct queued_file {
    char *path;
    struct queued_file *next;
} queued_file;

static queued_file *queue_head = NULL;
static queued_file *queue_tail = NULL;

static void enqueue_file(char *path) {
    queued_file *q = xmalloc(sizeof(queued_file));
    q->path = path;
    q->next = NULL;
    if (queue_tail == NULL) {
        queue_head = q;
    } else {
        queue_tail->next = q;
    }
    queue_tail = q;
}

void run_queued_files(void) {
    while (queue_head != NULL) {
        queued_file *q = queue_head;
        queue_head = q->next;
        if (queue_head == NULL) {
            queue_tail = NULL;
        }
        /* files from the queue start with a clean errno, like a fresh worker thread */
        zfile_errno = 0;
        errno = 0;
        search_file(q->path);
        free(q->path);
        free(q);
    }
}

/* ---- loop detection for followed symlinks ---- */

typedef struct {
    dev_t dev;
    ino_t ino;
} dirkey_t;

static dirkey_t *active_dirs = NULL;
static size_t active_len = 0;
static size_t active_cap = 0;

enum { LOOP_OK, LOOP_FOUND, LOOP_ERROR };

void reset_symloop_table(void) {
    active_len = 0;
}

static int symloop_enter(const char *path, dirkey_t *key) {
    struct stat st;
    size_t i;

    key->dev = 0;
    key->ino = 0;
    if (stat(path, &st) != 0) {
        log_err("Error stat()ing: %s", path);
        return LOOP_ERROR;
    }
    key->dev = st.st_dev;
    key->ino = st.st_ino;

    for (i = 0; i < active_len; i++) {
        if (active_dirs[i].dev == key->dev && active_dirs[i].ino == key->ino) {
            return LOOP_FOUND;
        }
    }
    if (active_len == active_cap) {
        active_cap = active_cap ? active_cap * 2 : 32;
        active_dirs = xrealloc(active_dirs, active_cap * sizeof(dirkey_t));
    }
    active_dirs[active_len++] = *key;
    return LOOP_OK;
}

static void symloop_leave(const dirkey_t *key) {
    size_t i;
    if (key->dev == 0 && key->ino == 0) {
        return;
    }
    for (i = active_len; i > 0; i--) {
        if (active_dirs[i - 1].dev == key->dev && active_dirs[i - 1].ino == key->ino) {
            memmove(&active_dirs[i - 1], &active_dirs[i], (active_len - i) * sizeof(dirkey_t));
            active_len--;
            return;
        }
    }
}

/* ---- searching buffers ---- */

static void literal_search(const char *buf, size_t buf_len, const char *path,
                           match_t **matches, size_t *matches_len, size_t *matches_cap, size_t spare) {
    size_t qlen = (size_t)opts.query_len;
    size_t offset = 0;
    int icase = opts.casing == CASE_INSENSITIVE;

    while (offset < buf_len) {
        const char *hit = literal_find(buf + offset, buf_len - offset, opts.query, qlen, icase);
        size_t start;
        if (hit == NULL) {
            break;
        }
        start = (size_t)(hit - buf);

        if (opts.word_regexp) {
            const char *end = hit + qlen;
            int ok_start = (hit == buf) || (word_char(*(hit - 1)) != opts.literal_starts_wordchar);
            int ok_end = (end == buf + buf_len) || (word_char(*end) != opts.literal_ends_wordchar);
            if (!(ok_start && ok_end)) {
                offset = start + 1;
                continue;
            }
        }

        grow_matches(matches, matches_cap, *matches_len + spare);
        (*matches)[*matches_len].start = start;
        (*matches)[*matches_len].end = start + qlen;
        offset = start + qlen;
        log_debug("Match found. File %s, offset %lu bytes.", path, (unsigned long)start);
        (*matches_len)++;

        if (opts.max_matches_per_file > 0 && *matches_len >= opts.max_matches_per_file) {
            log_err("Too many matches in %s. Skipping the rest of this file.", path);
            break;
        }
    }
}

static void regex_search(const char *buf, size_t buf_len, const char *path,
                         match_t **matches, size_t *matches_len, size_t *matches_cap, size_t spare) {
    int ov[3];
    size_t offset = 0;

    if (opts.multiline) {
        while (offset < buf_len &&
               pcre_exec(opts.re, opts.re_extra, buf, (int)buf_len, (int)offset, 0, ov, 3) >= 0) {
            log_debug("Regex match found. File %s, offset %i bytes.", path, ov[0]);
            if ((size_t)ov[1] > offset) {
                offset = (size_t)ov[1];
            } else {
                offset++;
            }
            if (ov[0] == ov[1]) {
                offset++;
                log_debug("Regex match is of length zero. Advancing offset one byte.");
            }

            grow_matches(matches, matches_cap, *matches_len + spare);
            (*matches)[*matches_len].start = (size_t)ov[0];
            (*matches)[*matches_len].end = (size_t)ov[1];
            (*matches_len)++;

            if (opts.max_matches_per_file > 0 && *matches_len >= opts.max_matches_per_file) {
                log_err("Too many matches in %s. Skipping the rest of this file.", path);
                break;
            }
        }
    } else {
        while (offset < buf_len) {
            const char *line;
            size_t line_len = next_line(&line, buf, buf_len, offset);
            size_t line_offset = 0;
            while (line_offset < line_len) {
                size_t line_to_buf;
                if (pcre_exec(opts.re, opts.re_extra, line, (int)line_len, (int)line_offset, 0, ov, 3) < 0) {
                    break;
                }
                line_to_buf = offset;
                log_debug("Regex match found. File %s, offset %i bytes.", path, ov[0]);
                if ((size_t)ov[1] > line_offset) {
                    line_offset = (size_t)ov[1];
                } else {
                    line_offset++;
                }
                if (ov[0] == ov[1]) {
                    line_offset++;
                    log_debug("Regex match is of length zero. Advancing offset one byte.");
                }

                grow_matches(matches, matches_cap, *matches_len + spare);
                (*matches)[*matches_len].start = (size_t)ov[0] + line_to_buf;
                (*matches)[*matches_len].end = (size_t)ov[1] + line_to_buf;
                (*matches_len)++;

                if (opts.max_matches_per_file > 0 && *matches_len >= opts.max_matches_per_file) {
                    log_err("Too many matches in %s. Skipping the rest of this file.", path);
                    return;
                }
            }
            offset += line_len + 1;
        }
    }
}

/*
 * Search one buffer. Returns non-zero if the buffer "counts" as matched for
 * the purpose of --files-without-matches (it had matches, or was skipped as binary).
 */
int search_buf(const char *buf, size_t buf_len, const char *path) {
    int binary = -1;
    match_t *matches = NULL;
    size_t matches_len = 0;
    size_t matches_cap = 0;
    size_t spare = 0;

    if (opts.search_stream) {
        binary = 0;
    } else if (!opts.search_binary_files) {
        binary = is_binary_buf((const unsigned char *)buf, buf_len);
        if (binary) {
            log_debug("File %s is binary. Skipping...", path);
            return 1;
        }
    }

    if (opts.invert_match) {
        matches_cap = 100;
        matches = xmalloc(matches_cap * sizeof(match_t));
        spare = 1;
    }

    if (!opts.literal && opts.query_len == 1 && opts.query[0] == '.') {
        if (matches == NULL) {
            matches_cap = 1;
            matches = xmalloc(matches_cap * sizeof(match_t));
        }
        matches[0].start = 0;
        matches[0].end = buf_len;
        matches_len = 1;
    } else if (opts.literal) {
        literal_search(buf, buf_len, path, &matches, &matches_len, &matches_cap, spare);
    } else {
        regex_search(buf, buf_len, path, &matches, &matches_len, &matches_cap, spare);
    }

    if (opts.invert_match) {
        matches_len = invert_match_list(buf, buf_len, matches, matches_len);
    }

    if (opts.stats) {
        stats.total_bytes += buf_len;
        stats.total_files++;
        stats.total_matches += matches_len;
        if (matches_len > 0) {
            stats.total_file_matches++;
        }
    }

    if (!opts.print_nonmatching_files && (matches_len > 0 || opts.print_all_paths)) {
        if (binary == -1 && !opts.print_filename_only) {
            binary = is_binary_buf((const unsigned char *)buf, buf_len);
        }
        if (opts.print_filename_only) {
            if (opts.print_count) {
                print_path_count(path, opts.path_sep, matches_len);
            } else {
                print_path(path, opts.path_sep);
            }
        } else if (binary) {
            print_binary_file_matches(path);
            flush_if_piped();
        } else {
            print_file_matches(path, buf, buf_len, matches, matches_len);
            flush_if_piped();
        }
        opts.match_found = 1;
    } else if (opts.search_stream && opts.passthrough) {
        fwrite(buf, 1, buf_len, out_fd);
    } else {
        log_debug("No match in %s", path);
    }

    if (matches_len == 0 && opts.search_stream) {
        print_context_append(buf, buf_len - 1);
    }

    free(matches);
    return matches_len > 0;
}

int search_stream(FILE *stream, const char *path) {
    char *line = NULL;
    size_t cap = 0;
    ssize_t len;
    int any = 0;

    print_init_context();

    while ((len = getline(&line, &cap, stream)) > 0) {
        any |= search_buf(line, (size_t)len, path);
        if (line[len - 1] == '\n') {
            len--;
        }
        print_trailing_context(path, line, (size_t)len);
    }

    free(line);
    print_cleanup_context();
    return any;
}

static void report_nonmatching(const char *path, int matched) {
    if (opts.print_nonmatching_files && !matched) {
        print_path(path, opts.path_sep);
        opts.match_found = 1;
    }
}

void search_file(const char *path) {
    int fd = -1;
    off_t f_len;
    char *buf = NULL;
    int mapped = 0;
    struct stat st;
    FILE *fp = NULL;
    int matched;

    if (stat(path, &st) != 0) {
        log_err("Skipping %s: Error fstat()ing file.", path);
        goto cleanup;
    }
    if (opts.stdout_inode != 0 && opts.stdout_inode == st.st_ino) {
        log_debug("Skipping %s: stdout is redirected to it", path);
        goto cleanup;
    }
    if (!S_ISREG(st.st_mode) && !S_ISFIFO(st.st_mode)) {
        log_err("Skipping %s: Mode %u is not a file.", path, (unsigned)st.st_mode);
        goto cleanup;
    }

    {
        int saved = errno;
        fd = open(path, O_RDONLY);
        if (fd < 0) {
            log_err("Skipping %s: Error opening file: %s", path, strerror(errno));
            goto cleanup;
        }
        errno = saved;
    }

    if (fstat(fd, &st) != 0) {
        log_err("Skipping %s: Error fstat()ing file.", path);
        goto cleanup;
    }
    if (opts.stdout_inode != 0 && opts.stdout_inode == st.st_ino) {
        log_debug("Skipping %s: stdout is redirected to it", path);
        goto cleanup;
    }
    if (!S_ISREG(st.st_mode) && !S_ISFIFO(st.st_mode)) {
        log_err("Skipping %s: Mode %u is not a file.", path, (unsigned)st.st_mode);
        goto cleanup;
    }

    print_init_context();

    if (S_ISFIFO(st.st_mode)) {
        log_debug("%s is a named pipe. stream searching", path);
        fp = fdopen(fd, "r");
        fd = -1;
        matched = search_stream(fp, path);
        fclose(fp);
        report_nonmatching(path, matched);
        goto cleanup;
    }

    f_len = st.st_size;

    if (f_len == 0) {
        if (opts.query[0] == '.' && opts.query_len == 1 && !opts.literal && opts.search_all_files) {
            matched = search_buf("", 0, path);
            report_nonmatching(path, matched);
        } else {
            log_debug("Skipping %s: file is empty.", path);
        }
        goto cleanup;
    }

    if (!opts.literal && f_len > INT_MAX) {
        log_err("Skipping %s: pcre_exec() can't handle files larger than %i bytes.", path, INT_MAX);
        goto cleanup;
    }

    {
        int saved = errno;
        if (opts.mmap) {
            buf = mmap(0, (size_t)f_len, PROT_READ, MAP_PRIVATE, fd, 0);
            if (buf == MAP_FAILED) {
                buf = NULL;
                log_err("File %s failed to load: %s.", path, strerror(errno));
                goto cleanup;
            }
            mapped = 1;
            madvise(buf, (size_t)f_len, MADV_SEQUENTIAL);
        } else {
            size_t got = 0;
            buf = xmalloc((size_t)f_len);
            while (got < (size_t)f_len) {
                ssize_t r = read(fd, buf + got, (size_t)f_len - got);
                if (r <= 0) {
                    break;
                }
                got += (size_t)r;
            }
            f_len = (off_t)got;
        }
        errno = saved;
    }

    if (opts.search_zip_files) {
        int ztype = detect_compression(buf, (size_t)f_len);
        if (ztype != ZTYPE_NONE) {
            log_debug("%s is a compressed file. stream searching", path);
            fp = zfile_open(fd, ztype);
            if (fp == NULL) {
                crash_like_original();
            }
            matched = search_stream(fp, path);
            fclose(fp);
            report_nonmatching(path, matched);
            goto cleanup;
        }
    }

    matched = search_buf(buf, (size_t)f_len, path);
    report_nonmatching(path, matched);

cleanup:
    print_cleanup_context();
    if (buf != NULL) {
        if (mapped) {
            munmap(buf, (size_t)f_len);
        } else {
            free(buf);
        }
    }
    if (fd != -1) {
        close(fd);
    }
}

static int dirent_alpha_dummy(void) {
    return 0;
}

/* Read a directory, keeping the entries the filter accepts (in readdir order). */
static int read_dir_entries(const char *dirname, struct dirent ***out, scandir_baton_t *baton) {
    DIR *d;
    struct dirent *entry;
    struct dirent **list = NULL;
    size_t len = 0, cap = 0;

    d = opendir(dirname);
    if (d == NULL) {
        return -1;
    }
    while ((entry = readdir(d)) != NULL) {
        struct dirent *copy;
        size_t sz;
        if (!filename_filter(dirname, entry, baton)) {
            continue;
        }
        if (len == cap) {
            cap = cap ? cap * 2 : 64;
            list = xrealloc(list, cap * sizeof(struct dirent *));
        }
        sz = offsetof(struct dirent, d_name) + strlen(entry->d_name) + 1;
        if (sz < sizeof(struct dirent)) {
            sz = sizeof(struct dirent);
        }
        copy = xmalloc(sz);
        memcpy(copy, entry, offsetof(struct dirent, d_name));
        strcpy(copy->d_name, entry->d_name);
        list[len++] = copy;
    }
    closedir(d);
    (void)dirent_alpha_dummy;
    *out = list;
    return (int)len;
}

static const char *const ignore_file_names[] = { ".ignore", ".gitignore", ".git/info/exclude", ".hgignore", NULL };

void search_dir(ignores *ig, const char *base_path, const char *path, int depth, dev_t original_dev) {
    struct dirent **entries = NULL;
    int count;
    int i;
    const char *path_start;
    scandir_baton_t baton;
    dirkey_t key;
    int loop;

    loop = symloop_enter(path, &key);
    if (loop == LOOP_FOUND) {
        log_err("Recursive directory loop: %s", path);
        symloop_leave(&key);
        return;
    }

    for (i = 0; opts.skip_vcs_ignores ? (i == 0) : (ignore_file_names[i] != NULL); i++) {
        char *ignore_path = xasprintf("%s/%s", path, ignore_file_names[i]);
        load_ignore_patterns(ig, ignore_path);
        free(ignore_path);
    }

    path_start = path;
    if (base_path) {
        size_t j;
        for (j = 0; base_path[j] && path[j] && base_path[j] == path[j]; j++) {
            path_start = path + j + 1;
        }
    }
    log_debug("search_dir: path is '%s', base_path is '%s', path_start is '%s'", path, base_path ? base_path : "(null)", path_start);

    baton.ig = ig;
    baton.base_path = base_path;
    baton.base_path_len = base_path ? strlen(base_path) : 0;
    baton.path_start = path_start;

    count = read_dir_entries(path, &entries, &baton);
    if (count == 0) {
        log_debug("No results found in directory %s", path);
        goto done;
    } else if (count == -1) {
        if (errno == ENOTDIR) {
            if (depth == 0 && opts.paths_len == 1) {
                if (opts.print_path == PATH_PRINT_DEFAULT || opts.print_path == PATH_PRINT_DEFAULT_EACH_LINE) {
                    opts.print_path = PATH_PRINT_NOTHING;
                }
                if (opts.only_matching && opts.print_path == PATH_PRINT_NOTHING) {
                    opts.print_line_numbers = 0;
                }
            }
            zfile_errno = ENOTDIR;
            search_file(path);
        } else {
            log_err("Error opening directory %s: %s", path, strerror(errno));
        }
        goto done;
    }

    for (i = 0; i < count; i++) {
        struct dirent *dir = entries[i];
        char *full = xasprintf("%s/%s", path, dir->d_name);
        int queued = 0;

        if (opts.one_dev) {
            struct stat s;
            if (lstat(full, &s) != 0) {
                log_err("Failed to get device information for %s. Skipping...", dir->d_name);
                goto next;
            }
            if (s.st_dev != original_dev) {
                log_debug("File %s crosses a device boundary (is probably a mount point.) Skipping...", dir->d_name);
                goto next;
            }
        }

        if (!opts.follow_symlinks && entry_is_symlink(path, dir)) {
            log_debug("File %s ignored becaused it's a symlink", dir->d_name);
            goto next;
        }

        if (!entry_is_directory(path, dir)) {
            if (opts.file_search_regex) {
                int ov[3];
                int rc = pcre_exec(opts.file_search_regex, opts.file_search_regex_extra, full, (int)strlen(full), 0, 0, ov, 3);
                if (rc < 0) {
                    log_debug("Skipping %s due to file_search_regex.", full);
                    goto next;
                } else if (opts.match_files) {
                    log_debug("match_files: file_search_regex matched for %s.", full);
                    print_path(full, opts.path_sep);
                    opts.match_found = 1;
                    goto next;
                }
            }
            enqueue_file(full);
            queued = 1;
            log_debug("%s added to work queue", full);
        } else if (opts.recurse_dirs) {
            if (depth < opts.max_search_depth || opts.max_search_depth == -1) {
                ignores *child;
                log_debug("Searching dir %s", full);
                child = init_ignore(ig, dir->d_name, strlen(dir->d_name));
                search_dir(child, base_path, full, depth + 1, original_dev);
                cleanup_ignore(child);
            } else {
                if (opts.max_search_depth == DEFAULT_MAX_SEARCH_DEPTH) {
                    log_err("Skipping %s. Use the --depth option to search deeper.", full);
                } else {
                    log_debug("Skipping %s. Use the --depth option to search deeper.", full);
                }
            }
        }

    next:
        free(dir);
        if (!queued) {
            free(full);
        }
    }

done:
    symloop_leave(&key);
    free(entries);
}
