#include <limits.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#include "log.h"
#include "options.h"
#include "print.h"
#include "util.h"

static const char *const color_reset = "\033[0m\033[K";
static const char *const truncate_marker = " [...]";

static int first_file_match = 1;

/*
 * Printing state. This persists across calls to print_file_matches() while
 * a single file (or stream) is being searched.
 */
static size_t line = 1;
static char **context_prev_lines = NULL;
static size_t prev_line = 0;
static size_t last_prev_line = 0;
static size_t prev_line_offset = 0;
static size_t lines_since_last_match = INT_MAX;
static int in_a_match = 0;
static int printing_a_match = 0;
static size_t last_printed_match = 0;

void flush_if_piped(void) {
    if (!isatty(fileno(stdout))) {
        fflush(out_fd);
    }
}

void print_init_context(void) {
    if (context_prev_lines != NULL) {
        return;
    }
    context_prev_lines = xcalloc(sizeof(char *), opts.before + 1);
    line = 1;
    prev_line = 0;
    last_prev_line = 0;
    prev_line_offset = 0;
    lines_since_last_match = INT_MAX;
    in_a_match = 0;
    printing_a_match = 0;
    last_printed_match = 0;
}

void print_cleanup_context(void) {
    size_t i;
    if (context_prev_lines == NULL) {
        return;
    }
    for (i = 0; i < opts.before; i++) {
        free(context_prev_lines[i]);
    }
    free(context_prev_lines);
    context_prev_lines = NULL;
}

void print_context_append(const char *ctx_line, size_t len) {
    if (opts.before == 0 || context_prev_lines == NULL) {
        return;
    }
    free(context_prev_lines[last_prev_line]);
    context_prev_lines[last_prev_line] = xstrndup(ctx_line, len);
    last_prev_line = (last_prev_line + 1) % opts.before;
}

const char *normalize_path(const char *path) {
    if (strlen(path) < 3) {
        return path;
    }
    if (path[0] == '.' && path[1] == '/') {
        return path + 2;
    }
    if (path[0] == '/' && path[1] == '/') {
        return path + 1;
    }
    return path;
}

void print_path(const char *path, char sep) {
    if (opts.print_path == PATH_PRINT_NOTHING && !opts.vimgrep) {
        return;
    }
    path = normalize_path(path);

    if (opts.ackmate) {
        fprintf(out_fd, ":%s%c", path, sep);
    } else if (opts.vimgrep) {
        fprintf(out_fd, "%s%c", path, sep);
    } else if (opts.color) {
        fprintf(out_fd, "%s%s%s%c", opts.color_path, path, color_reset, sep);
    } else {
        fprintf(out_fd, "%s%c", path, sep);
    }
}

void print_path_count(const char *path, char sep, size_t count) {
    if (*path) {
        print_path(path, ':');
    }
    if (opts.color) {
        fprintf(out_fd, "%s%lu%s%c", opts.color_line_number, (unsigned long)count, color_reset, sep);
    } else {
        fprintf(out_fd, "%lu%c", (unsigned long)count, sep);
    }
}

static void print_line_number(size_t n, char sep) {
    if (!opts.print_line_numbers) {
        return;
    }
    if (opts.color) {
        fprintf(out_fd, "%s%lu%s%c", opts.color_line_number, (unsigned long)n, color_reset, sep);
    } else {
        fprintf(out_fd, "%lu%c", (unsigned long)n, sep);
    }
}

static void print_column_number(const match_t matches[], size_t idx, size_t line_offset, char sep) {
    size_t column = 0;
    if (line_offset <= matches[idx].start) {
        column = (matches[idx].start - line_offset) + 1;
    }
    fprintf(out_fd, "%lu%c", (unsigned long)column, sep);
}

static void print_file_separator(void) {
    if (first_file_match == 0 && opts.print_break) {
        fprintf(out_fd, "\n");
    }
    first_file_match = 0;
}

void print_binary_file_matches(const char *path) {
    path = normalize_path(path);
    print_file_separator();
    fprintf(out_fd, "Binary file %s matches.\n", path);
}

static void print_line(const char *buf, size_t buf_pos, size_t line_offset) {
    size_t write_chars = buf_pos - line_offset;
    if (opts.width > 0 && opts.width < write_chars) {
        write_chars = opts.width;
    }
    fwrite(buf + line_offset, 1, write_chars, out_fd);
    fputc('\n', out_fd);
}

void print_trailing_context(const char *path, const char *buf, size_t n) {
    char sep = '-';

    if (opts.ackmate || opts.vimgrep) {
        sep = ':';
    }

    if (lines_since_last_match != 0 && lines_since_last_match <= opts.after) {
        if (opts.print_path == PATH_PRINT_EACH_LINE) {
            print_path(path, ':');
        }
        print_line_number(line, sep);
        fwrite(buf, 1, n, out_fd);
        fputc('\n', out_fd);
    }

    line++;
    if (lines_since_last_match < INT_MAX) {
        lines_since_last_match++;
    }
}

void print_file_matches(const char *path, const char *buf, size_t buf_len, const match_t matches[], size_t matches_len) {
    size_t cur_match = 0;
    ssize_t lines_to_print = 0;
    char sep = '-';
    size_t i, j;
    int blanks_between_matches = opts.context || opts.after || opts.before;

    if (opts.ackmate || opts.vimgrep) {
        sep = ':';
    }

    print_file_separator();

    if (opts.print_path == PATH_PRINT_DEFAULT) {
        opts.print_path = PATH_PRINT_TOP;
    } else if (opts.print_path == PATH_PRINT_DEFAULT_EACH_LINE) {
        opts.print_path = PATH_PRINT_EACH_LINE;
    }

    if (opts.print_path == PATH_PRINT_TOP) {
        if (opts.print_count) {
            print_path_count(path, opts.path_sep, matches_len);
        } else {
            print_path(path, opts.path_sep);
        }
    }

    for (i = 0; i <= buf_len && (cur_match < matches_len || lines_since_last_match <= opts.after); i++) {
        if (cur_match < matches_len && i == matches[cur_match].start) {
            in_a_match = 1;
            if (cur_match > 0 && blanks_between_matches && lines_since_last_match > (opts.before + opts.after + 1)) {
                fprintf(out_fd, "--\n");
            }

            if (lines_since_last_match > 0 && opts.before > 0) {
                lines_to_print = (ssize_t)(lines_since_last_match - (opts.after + 1));
                if (lines_to_print < 0) {
                    lines_to_print = 0;
                } else if ((size_t)lines_to_print > opts.before) {
                    lines_to_print = (ssize_t)opts.before;
                }

                for (j = (opts.before - (size_t)lines_to_print); j < opts.before; j++) {
                    prev_line = (last_prev_line + j) % opts.before;
                    if (context_prev_lines[prev_line] != NULL) {
                        if (opts.print_path == PATH_PRINT_EACH_LINE) {
                            print_path(path, ':');
                        }
                        print_line_number(line - (opts.before - j), sep);
                        fprintf(out_fd, "%s\n", context_prev_lines[prev_line]);
                    }
                }
            }
            lines_since_last_match = 0;
        }

        if (cur_match < matches_len && i == matches[cur_match].end) {
            cur_match++;
            in_a_match = 0;
        }

        if ((i == buf_len || buf[i] == '\n') && opts.before > 0) {
            print_context_append(&buf[prev_line_offset], i - prev_line_offset);
        }

        if (i == buf_len || buf[i] == '\n') {
            if (lines_since_last_match == 0) {
                if (opts.print_path == PATH_PRINT_EACH_LINE && !opts.search_stream) {
                    print_path(path, ':');
                }
                if (opts.ackmate) {
                    print_line_number(line, ';');
                    for (; last_printed_match < cur_match; last_printed_match++) {
                        long start = (long)(matches[last_printed_match].start - prev_line_offset);
                        if (start < 0) {
                            start = 0;
                        }
                        fprintf(out_fd, "%li %li", start,
                                (long)(matches[last_printed_match].end - matches[last_printed_match].start));
                        fputc(last_printed_match == cur_match - 1 ? ':' : ',', out_fd);
                    }
                    print_line(buf, i, prev_line_offset);
                } else if (opts.vimgrep) {
                    for (; last_printed_match < cur_match; last_printed_match++) {
                        print_path(path, sep);
                        print_line_number(line, sep);
                        print_column_number(matches, last_printed_match, prev_line_offset, sep);
                        print_line(buf, i, prev_line_offset);
                    }
                } else {
                    int printed_match = 0;
                    print_line_number(line, ':');
                    if (opts.column) {
                        print_column_number(matches, last_printed_match < matches_len ? last_printed_match : matches_len - 1,
                                            prev_line_offset, ':');
                    }

                    if (printing_a_match && opts.color) {
                        fprintf(out_fd, "%s", opts.color_match);
                    }
                    for (j = prev_line_offset; j <= i; j++) {
                        if (last_printed_match < matches_len && j == matches[last_printed_match].end) {
                            if (opts.color) {
                                fprintf(out_fd, "%s", color_reset);
                            }
                            printing_a_match = 0;
                            last_printed_match++;
                            printed_match = 1;
                            if (opts.only_matching) {
                                fputc('\n', out_fd);
                            }
                        }
                        if (j < buf_len && opts.width > 0 && j - prev_line_offset >= opts.width) {
                            if (j < i) {
                                fputs(truncate_marker, out_fd);
                            }
                            fputc('\n', out_fd);
                            j = i;
                            last_printed_match = matches_len;
                        }
                        if (last_printed_match < matches_len && j == matches[last_printed_match].start) {
                            if (opts.only_matching && printed_match) {
                                if (opts.print_path == PATH_PRINT_EACH_LINE) {
                                    print_path(path, ':');
                                }
                                print_line_number(line, ':');
                                if (opts.column) {
                                    print_column_number(matches, last_printed_match, prev_line_offset, ':');
                                }
                            }
                            if (opts.color) {
                                fprintf(out_fd, "%s", opts.color_match);
                            }
                            printing_a_match = 1;
                        }
                        if (j < buf_len) {
                            if (!opts.only_matching || printing_a_match) {
                                if (opts.width == 0 || j - prev_line_offset < opts.width) {
                                    fputc(buf[j], out_fd);
                                }
                            }
                        }
                    }
                    if (printing_a_match && opts.color) {
                        fprintf(out_fd, "%s", color_reset);
                    }
                }
            }

            if (opts.search_stream) {
                last_printed_match = 0;
                break;
            }

            if (lines_since_last_match > 0 && lines_since_last_match <= opts.after) {
                if (opts.print_path == PATH_PRINT_EACH_LINE) {
                    print_path(path, ':');
                }
                print_line_number(line, sep);
                fwrite(&buf[prev_line_offset], 1, i - prev_line_offset, out_fd);
                fputc('\n', out_fd);
            }

            prev_line_offset = i + 1;
            line++;
            if (!in_a_match && lines_since_last_match < INT_MAX) {
                lines_since_last_match++;
            }
            if (i == buf_len && buf_len > 0 && buf[i - 1] != '\n') {
                fputc('\n', out_fd);
            }
        }
    }
}
