#define _GNU_SOURCE
#include <errno.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#include <lzma.h>
#include <zlib.h>

#include "log.h"
#include "util.h"
#include "zfile.h"

#define ZIN_SIZE (32 * 1024)

int zfile_errno = 0;

typedef struct {
    FILE *in;
    int ztype;
    int done;
    z_stream gz;
    lzma_stream xz;
    unsigned char inbuf[ZIN_SIZE];
} zcookie_t;

int detect_compression(const void *buf, size_t len) {
    const unsigned char *b = buf;

    if (len == 0) {
        return ZTYPE_NONE;
    }
    if (len >= 2 && b[0] == 0x1F) {
        if (b[1] == 0x8B) {
            log_debug("Found gzip-based stream");
            return ZTYPE_GZIP;
        } else if (b[1] == 0x9B) {
            log_debug("Found compress-based stream");
            return ZTYPE_COMPRESS;
        }
    }
    if (len >= 6 && b[0] == 0xFD && b[1] == 0x37 && b[2] == 0x7A && b[3] == 0x58 && b[4] == 0x5A && b[5] == 0x00) {
        log_debug("Found xz based stream");
        return ZTYPE_XZ;
    }
    if (len >= 4 && b[0] == 0x50 && b[1] == 0x4B && b[2] == 0x03 && b[3] == 0x04) {
        log_debug("Found zip based stream");
        return ZTYPE_ZIP;
    }
    return ZTYPE_NONE;
}

void crash_like_original(void) {
    signal(SIGSEGV, SIG_DFL);
    raise(SIGSEGV);
    abort();
}

static void truncated(void) {
    const char *prog = program_invocation_short_name;
    fprintf(stderr, "%s: truncated file: %s\n", prog, strerror(zfile_errno));
    exit(1);
}

static size_t avail_in(zcookie_t *c) {
    return c->ztype == ZTYPE_GZIP ? c->gz.avail_in : c->xz.avail_in;
}

static size_t avail_out(zcookie_t *c) {
    return c->ztype == ZTYPE_GZIP ? c->gz.avail_out : c->xz.avail_out;
}

static ssize_t zcookie_read(void *cookie, char *buf, size_t size) {
    zcookie_t *c = cookie;
    int refilled = 0;

    if (size == 0 || c->done) {
        return 0;
    }

    if (c->ztype == ZTYPE_GZIP) {
        c->gz.next_out = (Bytef *)buf;
        c->gz.avail_out = (uInt)size;
    } else {
        c->xz.next_out = (uint8_t *)buf;
        c->xz.avail_out = size;
    }

    for (;;) {
        int ended = 0;

        if (avail_in(c) == 0) {
            size_t nb = fread(c->inbuf, 1, sizeof(c->inbuf), c->in);
            if (ferror(c->in)) {
                fprintf(stderr, "%s: error read core: %s\n", program_invocation_short_name, strerror(zfile_errno));
                exit(1);
            }
            if (nb == 0 && feof(c->in)) {
                truncated();
            }
            if (c->ztype == ZTYPE_GZIP) {
                c->gz.next_in = c->inbuf;
                c->gz.avail_in = (uInt)nb;
            } else {
                c->xz.next_in = c->inbuf;
                c->xz.avail_in = nb;
            }
            refilled = 1;
        }

        if (c->ztype == ZTYPE_GZIP) {
            int ret = inflate(&c->gz, Z_NO_FLUSH);
            if (ret != Z_OK && ret != Z_STREAM_END) {
                log_err("Found mem/data error while decompressing zlib stream: %s", zError(ret));
                return -1;
            }
            ended = ret == Z_STREAM_END;
        } else {
            lzma_ret ret = lzma_code(&c->xz, LZMA_RUN);
            if (ret != LZMA_OK && ret != LZMA_STREAM_END) {
                log_err("Found mem/data error while decompressing xz/lzma stream: %d", (int)ret);
                return -1;
            }
            ended = ret == LZMA_STREAM_END;
        }

        if (avail_out(c) == 0) {
            return (ssize_t)size;
        }
        if (ended) {
            if (!refilled) {
                truncated();
            }
            c->done = 1;
            return (ssize_t)(size - avail_out(c));
        }
    }
}

static int zcookie_close(void *cookie) {
    zcookie_t *c = cookie;
    if (c->ztype == ZTYPE_GZIP) {
        inflateEnd(&c->gz);
    } else {
        lzma_end(&c->xz);
    }
    fclose(c->in);
    free(c);
    return 0;
}

FILE *zfile_open(int fd, int ztype) {
    zcookie_t *c;
    cookie_io_functions_t fns = { zcookie_read, NULL, NULL, zcookie_close };
    FILE *fp;
    int dupfd;

    if (ztype != ZTYPE_GZIP && ztype != ZTYPE_XZ) {
        log_err("Unsupported compression type: %d", ztype);
        return NULL;
    }

    c = xcalloc(1, sizeof(zcookie_t));
    c->ztype = ztype;

    if (ztype == ZTYPE_GZIP) {
        if (inflateInit2(&c->gz, 32 + 15) != Z_OK) {
            free(c);
            return NULL;
        }
    } else {
        lzma_stream init = LZMA_STREAM_INIT;
        c->xz = init;
        if (lzma_stream_decoder(&c->xz, UINT64_MAX, 0) != LZMA_OK) {
            free(c);
            return NULL;
        }
    }

    dupfd = dup(fd);
    if (dupfd < 0) {
        zcookie_close(c);
        return NULL;
    }
    lseek(dupfd, 0, SEEK_SET);
    c->in = fdopen(dupfd, "r");
    if (c->in == NULL) {
        close(dupfd);
        free(c);
        return NULL;
    }

    fp = fopencookie(c, "r", fns);
    if (fp == NULL) {
        zcookie_close(c);
        return NULL;
    }
    return fp;
}
